sp_widget.client_script:
api.controller = function($scope, $timeout) {
    var c = this;
    // ✅ STACKED TOASTS 
    c.toasts = [];


    c.addToast = function(type, message) {
        var toast = {
            type: type,
            message: message
        };
        c.toasts.push(toast);


        if (type !== 'error') {
            $timeout(function() {
                var index = c.toasts.indexOf(toast);
                if (index > -1) {
                    c.toasts.splice(index, 1);
                }
            }, 5000);
        }
    };


    c.removeToast = function(index) {
        c.toasts.splice(index, 1);
    };


    c.clearErrorToasts = function() {
        c.toasts = c.toasts.filter(function(toast) {
            return toast.type !== 'error';
        });
    };


    c.tenants = [];


    c.loadTenants = function() {
        c.server.get({
            action: 'getTenants'
        }).then(function(res) {
            var tenants = res.data.tenants || [];
            tenants.forEach(function(t) {
                t.show_warning = (t.show_warning == 'true' || t.show_warning == '1');
                t.warning_visible = false;
            });
            c.tenants = tenants;
        });
    };


    c.$onInit = function() {
        c.loadTenants();
    };


    $scope.$on('setup.reset', function() {
        c.tenants = [];
    });


    $scope.$on('setup.completed', function() {
        $timeout(function() {
            c.loadTenants();
        }, 2000);
    });


    // Warn when user activates a flagged tenant
    c.onActiveChange = function(tenant) {


        if (tenant.active !== 'true') {
            tenant.warning_visible = false;
            return;
        }


        if (tenant.show_warning) {
            tenant.warning_visible = true;
            c.addToast(
                'error',
                '⚠️ Warning: "' + tenant.tenant +
                '" was not found in the latest WEX API response. ' +
                'It may have been manually created or deleted from WEX. ' +
                'It will be deactivated on the next refresh.'
            );
        }
    };


    c.saveAll = function() {
        var payload = [];
        c.tenants.forEach(function(t) {
            payload.push({
                sys_id: t.sys_id,
                active: t.active
            });
        });


        c.server.get({
            action: 'saveAll',
            tenants: payload
        }).then(function(res) {
            $timeout(function() {
                c.loadTenants();
            }, 500);


            $timeout(function() {
                c.clearErrorToasts();


                if (res.data.saveResult && res.data.saveResult.success) {
                    var warnings = res.data.saveResult.warnings || [];
                    if (warnings.length > 0) {
                        c.addToast('error',
                            '⚠️ Saved, but tenant(s) "' + warnings.join(', ') +
                            '" were not found in the latest WEX API response and will be deactivated on the next refresh.');
                    } else {
                        c.addToast('success', 'All changes saved ✅');
                    }
                } else {
                    c.addToast('error', 'Error saving changes ❌');
                }
            }, 800);
        });
    };


    c.refreshTenants = function() {
        c.server.get({
            action: 'refreshTenants'
        }).then(function() {
            $timeout(function() {
                c.loadTenants();
            }, 2000);


            $timeout(function() {
                c.clearErrorToasts();
                c.addToast('success', 'Tenants refreshed ✅');
            }, 2500);
        });
    };
};

sp_widget.css:
/* ═══════════════════════════════════════════
   PANEL — matches hp-wxp-event-management-status
   ═══════════════════════════════════════════ */
.hp-tenant-widget {
  border: 2px solid #e5e7eb !important;
  border-radius: 10px;
  box-shadow: 0 2px 6px rgba(0,0,0,0.05);
  position: relative;
}

.hp-tenant-widget .panel-heading {
  background: #f9fafb !important;
  border-bottom: 1px solid #e5e7eb;
  padding: 10px 14px;
  border-radius: 10px 10px 0 0;
}

.mapping-subtitle {
  color: #64748b;
  font-size: 13px;
  margin: 0 0 16px 0;
}
/* ═══════════════════════════════════════════
   GLOBAL TOAST (TOP RIGHT)
   ═══════════════════════════════════════════ */
.toast-container {
  position: fixed;
  top: 20px;
  right: 20px;
  z-index: 9999;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.tenant-toast-global {
  position: relative;
  background: #ecfdf5;
  color: #065f46;
  border: 1px solid #a7f3d0;
  padding: 14px 40px 14px 14px;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 500;
  box-shadow: 0 6px 16px rgba(0,0,0,0.15);
  max-width: 350px;
  animation: slideIn 0.3s ease;
}


.tenant-toast-global.toast-error {
  background: #fef2f2;
  color: #991b1b;
  border-color: #fecaca;
}


.toast-text {
  display: block;
}


.toast-close {
  position: absolute;
  top: 8px;
  right: 10px;
  cursor: pointer;
  font-weight: bold;
  font-size: 14px;
}


.toast-close:hover {
  opacity: 0.6;
}


@keyframes slideIn {
  from {
    opacity: 0;
    transform: translateX(20px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

/* ═══════════════════════════════════════════
   HEADER — flex layout with title + buttons
   ═══════════════════════════════════════════ */
.hp-tenant-widget .header-flex {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.hp-tenant-widget .title {
  font-size: 16px;
  font-weight: 600;
  color: #1f2937;
}

.hp-tenant-widget .header-actions {
  display: flex;
  gap: 8px;
}



/* ═══════════════════════════════════════════
   PANEL BODY
   ═══════════════════════════════════════════ */
.hp-tenant-widget .panel-body {
  padding: 14px;
}


/* ═══════════════════════════════════════════
   TABLE — matches status widget
   ═══════════════════════════════════════════ */
.hp-tenant-widget .table {
  background: white;
  border-radius: 8px;
  margin-bottom: 0;
}

.hp-tenant-widget .table thead {
  background: #f9fafb;
}

.hp-tenant-widget .table thead th {
  font-size: 13px;
  font-weight: 600;
  color: #1f2937;
  border-bottom: 2px solid #e5e7eb;
  padding: 10px;
}

.hp-tenant-widget .table tbody td {
  font-size: 13px;
  color: #374151;
  padding: 10px;
  vertical-align: middle;
}

.hp-tenant-widget .table tbody tr {
  transition: background 0.15s ease;
}

.hp-tenant-widget .table tbody tr:hover {
  background: #f3f4f6;
}


/* ═══════════════════════════════════════════
   ACTIVE ROW — green highlight
   ═══════════════════════════════════════════ */
.hp-tenant-widget .active-row {
  background: #ecfdf5 !important;
  border-left: 4px solid #22c55e;
}

.hp-tenant-widget .active-row td {
  color: #14532d;
  font-weight: 500;
}

.hp-tenant-widget .active-row:hover {
  background: #dcfce7 !important;
}


/* ═══════════════════════════════════════════
   LOCKED BADGE — single tenant read-only
   ═══════════════════════════════════════════ */
.hp-tenant-widget .tenant-locked-badge {
  display: inline-block;
  padding: 3px 10px;
  font-size: 12px;
  font-weight: 600;
  color: #065f46;
  background: #d1fae5;
  border-radius: 12px;
}


/* ═══════════════════════════════════════════
   INLINE SELECT
   ═══════════════════════════════════════════ */
.hp-tenant-widget select.form-control {
  font-size: 12px;
  height: 30px;
  padding: 4px 8px;
  border-radius: 6px;
  border: 1px solid #d1d5db;
  max-width: 120px;
}

.hp-tenant-widget select.form-control:focus {
  border-color: #0076ce;
  box-shadow: 0 0 0 1px #0076ce;
  outline: none;
}


/* ═══════════════════════════════════════════
   EMPTY STATE
   ═══════════════════════════════════════════ */
.hp-tenant-widget .empty-state {
  text-align: center;
  padding: 30px 20px;
  color: #9ca3af;
}

.hp-tenant-widget .empty-state p {
  font-size: 13px;
  margin: 0;
}


/* ═══════════════════════════════════════════
   RESPONSIVE
   ═══════════════════════════════════════════ */
@media (max-width: 600px) {
  .hp-tenant-widget .header-flex {
    flex-direction: column;
    gap: 8px;
    align-items: flex-start;
  }
  .hp-tenant-widget .table thead th,
  .hp-tenant-widget .table tbody td {
    font-size: 11px;
    padding: 6px;
  }
}
/* ═══════════════════════════════════════════
   WARNING ROW (AMBER)
   ═══════════════════════════════════════════ */
.hp-tenant-widget .warning-row {
  background: #fffbeb !important;
  border-left: 4px solid #f59e0b;
}
.hp-tenant-widget .warning-row td {
  color: #92400e;
}


.hp-tenant-widget .warning-row:hover {
  background: #fef3c7 !important;
}


.hp-tenant-widget .warning-row.active-row {
  background: #fef3c7 !important;
  border-left: 4px solid #f59e0b;
}


/* ═══════════════════════════════════════════
   WARNING ICON
   ═══════════════════════════════════════════ */
.hp-tenant-widget .warning-icon {
  margin-right: 4px;
  font-size: 14px;
}

sp_widget.script:
(function() {
    var TENANT_TABLE = 'x_hpws_wrkfrcexpam_tenant_list';
    var LOG = 'HP WXP AM: ';
    var action = input && input.action;

    // ═══════════════════════════════════════════
    // SAVE ALL
    // ═══════════════════════════════════════════
    if (action === 'saveAll') {
        data.saveResult = {
            success: false,
            warnings: []
        };
        var items = input.tenants || [];
        var allOk = true;

        for (var i = 0; i < items.length; i++) {
            var item = items[i];
            if (item && item.sys_id) {
                var tenantGr = new GlideRecordSecure(TENANT_TABLE);
                if (tenantGr.get(item.sys_id)) {

                    // Warn if activating a flagged tenant
                    if (item.active === 'true' &&
                        tenantGr.getValue('show_warning') == '1') {
                        data.saveResult.warnings.push(tenantGr.getValue('tenant'));
                    }

                    tenantGr.setValue('active', item.active === 'true');
                    tenantGr.update();
                } else {
                    allOk = false;
                }
            }
        }

        data.saveResult.success = allOk;
        return;
    }

    // ═══════════════════════════════════════════
    // REFRESH TENANTS
    // ═══════════════════════════════════════════
    if (action === 'refreshTenants') {
        data.refreshResult = {
            success: false,
            message: ''
        };

        try {
            var apiKey   = gs.getProperty('x_hpws_wrkfrcexpam.api.fastn.api.key');
            var baseUrl  = gs.getProperty('x_hpws_wrkfrcexpam.fastn_api_baseurl');
            var tenantId = gs.getProperty('x_hpws_wrkfrcexpam.tenants');
            var spaceId  = gs.getProperty('x_hpws_wrkfrcexpam.fastn.space.id');

            if (!apiKey || !baseUrl || !tenantId || !spaceId) {
                data.refreshResult.message = 'Alert Management is not fully configured.';
                gs.warn(LOG + 'Refresh aborted - fastn properties missing.');
                return;
            }

            var endpoint = baseUrl + '/api/v1/getTenantsChildren';

            var r = new sn_ws.RESTMessageV2();
            r.setEndpoint(endpoint);
            r.setHttpMethod('POST');

            r.setRequestHeader('Content-Type', 'application/json');
            r.setRequestHeader('fastn-space-id', spaceId);
            r.setRequestHeader('stage', 'LIVE');
            r.setRequestHeader('x-fastn-api-key', apiKey);
            r.setRequestHeader('x-fastn-space-tenantid', tenantId);

            r.setRequestBody(JSON.stringify({
                input: {}
            }));

            var response = r.execute();
            var status   = response.getStatusCode();
            var body     = response.getBody();   


            if (status < 200 || status >= 300) {
                data.refreshResult.message = 'WEX API returned HTTP ' + status + '.';
                gs.error(LOG + 'Refresh failed - HTTP ' + status);
                return;
            }

            var record = JSON.parse(body);

            if (record.tenantType != 'PARTNER' && record.tenantType != 'CUSTOMER') {
                data.refreshResult.message = 'Unexpected tenantType: ' + record.tenantType;
                gs.error(LOG + 'Unexpected tenantType: ' + record.tenantType);
                return;
            }

            var apiTenants   = record.tenants || [];
            var apiTenantIds = [];
            var processed    = 0;

            for (var j = 0; j < apiTenants.length; j++) {
                var t = apiTenants[j];
                if (!t || !t.tenantId)
                    continue;

                // For a PARTNER the partner's own tenant is not a selectable child.
                // For a CUSTOMER the API returns the tenant itself - keep it.
                if (record.tenantType == 'PARTNER' && tenantId == t.tenantId)
                    continue;

                apiTenantIds.push(t.tenantId);

                var grT = new GlideRecordSecure(TENANT_TABLE);
                grT.addQuery('tenantid', t.tenantId);
                grT.query();
                if (grT.next()) {
                    grT.setValue('tenant', t.name);
                    grT.setValue('show_warning', false);
                    grT.update();
                } else {
                    grT.initialize();
                    grT.setValue('tenant', t.name);
                    grT.setValue('tenantid', t.tenantId);
                    grT.setValue('active', false);
                    grT.setValue('show_warning', false);
                    grT.insert();
                }
                processed++;
            }

            // Flag anything the API no longer returns (manual rows + deleted tenants)
            if (apiTenantIds.length > 0) {
                var grStale = new GlideRecordSecure(TENANT_TABLE);
                grStale.addQuery('tenantid', 'NOT IN', apiTenantIds.join(','));
                grStale.query();
                while (grStale.next()) {
                    grStale.setValue('active', false);
                    grStale.setValue('show_warning', true);
                    grStale.update();
                    gs.info(LOG + 'Deactivated tenant not in API: ' +
                            grStale.getValue('tenant') + ' (' + grStale.getValue('tenantid') + ')');
                }
            }

            gs.info(LOG + 'Tenant refresh complete (' + record.tenantType +
                    '). Processed ' + processed + ' of ' + apiTenants.length + ' tenants.');

            data.refreshResult.success = true;
            data.refreshResult.message = 'Processed ' + processed + ' tenant(s).';

        } catch (e) {
            data.refreshResult.message = e.message;
            gs.error(LOG + 'Refresh error: ' + e);
            return;
        }

        // fall through to LOAD TENANTS so the client gets the fresh list immediately
    }

    // ═══════════════════════════════════════════
    // LOAD TENANTS
    // ═══════════════════════════════════════════
    if (action === 'getTenants' || action === 'refreshTenants' || !action) {
        data.tenants = [];

        var tenantlist = new GlideRecordSecure(TENANT_TABLE);
        tenantlist.orderBy('tenant');
        tenantlist.query();

        var allTenants = [];
        while (tenantlist.next()) {
            allTenants.push({
                sys_id: tenantlist.getUniqueValue(),
                tenant: tenantlist.getValue('tenant') || '',
                tenantid: tenantlist.getValue('tenantid') || '',
                active: tenantlist.getValue('active') == '1' ? 'true' : 'false',
                show_warning: tenantlist.getValue('show_warning')
            });
        }

        // Single tenant: force active to true if false (only for non-warning records)
        if (allTenants.length === 1 && allTenants[0].active !== 'true' &&
            allTenants[0].show_warning != '1') {
            var fix = new GlideRecordSecure(TENANT_TABLE);
            if (fix.get(allTenants[0].sys_id)) {
                fix.setValue('active', true);
                fix.update();
            }
            allTenants[0].active = 'true';
        }

        data.tenants = allTenants;
    }

})();
